// museaal.ee — "Art by mood", the free-text reader.
//
// A Cloudflare Worker. A visitor's sentence, in Estonian or English, comes in; Claude
// Haiku picks the words from the catalogue's mood vocabulary that best describe the
// pictures they are after; the words go back to the page, which ranks the pictures
// itself from the scores it already has. Nothing but the sentence leaves the visitor's
// browser, and nothing is stored.
//
// GENERATED by build_mood.py -- do not edit; from data/moods.json: edit worker/template.js, not
// worker/mood-worker.js. After a change to the vocabulary, paste mood-worker.js into
// the Worker again (worker/README.md).
//
// A second door, POST /ask, is the "Find art for your home" page's assistant (find.html): the conversation so far
// comes in with the page's own controls (price, medium, size, mood) as the visitor has set
// them, and Claude answers with a short reply and the whole search it implies -- words from
// the same vocabulary, title words, media, a size, a budget, an artist. The page sets its
// controls to that, picks the works for sale itself, and shows them under the reply.
// Nothing is stored here either.
//
// A page that sends tools: 1 lets Claude look first: it may call search, artist and similar in
// up to two rounds a turn. The page runs them on the stock it has loaded (2 MB, too much to read
// here) and posts the conversation again with the results; the last answer adds up to five picks.
//
// A third, /list/*, keeps a signed-in visitor's My List (below, at list()).
//
// Needs one secret, ANTHROPIC_API_KEY (Settings > Variables and Secrets); /list/* needs more (worker/README.md).
// With a second, TURNSTILE_SECRET, the two doors that call Claude answer only a visitor who has passed Cloudflare
// Turnstile: the page's token buys a pass for half an hour (at human(), below). Without it they answer anyone.
// The same secret puts Turnstile in front of /list/login, which sends email.
// The backoffice (museaal.ee/admin, /admin/stats below) needs ADMIN_KEY, and GOATCOUNTER_TOKEN for the visits.
// Calls the Messages API with fetch: the dashboard's editor takes one file, no build step.

const WORDS = ["solemn", "serene", "contemplative", "melancholy", "lonely", "nostalgic", "tender", "intimate", "joyful", "playful", "festive", "romantic", "dreamy", "mysterious", "eerie", "anxious", "gloomy", "dramatic", "heroic", "bright", "dark", "sunny", "golden", "twilight", "moonlit", "misty", "vivid", "muted", "warm", "cold", "stormy", "still", "wintry", "spring", "summery", "autumnal", "hopeful", "cosy", "sacred", "majestic", "fragile", "sensual", "innocent", "energetic", "proud", "elegant", "lively", "empty", "spiritual", "idyllic", "wild", "harsh", "angry", "abstract", "expressive", "decorative", "simple", "ornate", "rustic", "modern", "sea", "lake", "river", "forest", "trees", "fields", "garden", "mountains", "sky", "village", "city", "harbour", "church", "interior", "portrait", "children", "family", "work", "music", "dance", "horses", "animals", "birds", "flowers", "stilllife", "boats"];
const MODEL = "claude-haiku-5-5";
const ORIGINS = ["https://museaal.ee", "https://www.museaal.ee"];
const PER_MINUTE = 20;          // searches and turns per visitor per minute, per Worker instance (both doors)
const CALLS_PER_MINUTE = 60;    // all requests, a turn's tool rounds included
const ASK_PER_DAY = 2000;       // Buy Art questions a day, all visitors together (the c:ask counter): past it /ask rests till midnight UTC

const SYSTEM = "You match a visitor's words to a museum's picture search. The museum has scored every picture in " +
  "its collection of Estonian art against a fixed list of words: moods, light, colour, season and weather, and " +
  "subjects. Read what the visitor wrote, in Estonian or English, and pick the words from the list that best " +
  "describe the pictures they are looking for, most important first: one to five words. Read the feeling behind " +
  "the words as well as the literal subjects. For the kind of work, answer 'keep' unless the visitor names one: " +
  "'paint' if they ask for paintings, 'paper' for drawings, prints or sketches, 'all' if they ask for anything " +
  "including sculpture. Words: " + WORDS.join(", ");

const SCHEMA = {
  type: "object",
  properties: {
    words: { type: "array", items: { type: "string", enum: WORDS } },
    kind: { type: "string", enum: ["keep", "paint", "paper", "all"] },
  },
  required: ["words", "kind"],
  additionalProperties: false,
};

const ASK_HEAD = "You are the search desk on museaal.ee, a catalogue of Estonian art. On this page visitors look for a " +
  "work to buy among the several thousand works the catalogue's galleries have for sale now, at asking prices from " +
  "tens of euros to tens of thousands (most paintings between a few hundred and a few thousand). The page also has " +
  "controls the visitor sets by hand: a price range, the medium, the size and mood words. Each turn you write a short " +
  "reply and return the whole search; the page sets its controls to your search and shows the twelve works that match it " +
  "best under your reply. ";
const BLIND = "You do not see the works before they are shown, so never name or describe a particular work, " +
  "and never say what is available or what things cost; earlier turns note what was shown and how many works matched.\n\n";
const LOOK = "Before you answer you can look at the stock with three tools, which the page runs on the list it shows: search " +
  "(the works a search admits, best first: how many, and the first ten not yet shown in this conversation, each with an id, " +
  "title, artist, technique, size, asking price, gallery and its strongest mood words), artist (one artist's works for sale, " +
  "how many works the museums hold, and their auction record) and similar (the works for sale closest to one work in mood " +
  "and medium). When there is anything to search on, search before you answer and look at what it found. If it found " +
  "nothing or only poor matches, change one thing -- a wider budget, one mood word fewer, a related medium -- and " +
  "search again, keeping the title terms for what the visitor named (a season, a place, a subject): a title is the surest " +
  "sign of a subject, the mood words only a guess. When the visitor names an artist, call artist in the same round as the first search. Call similar only " +
  "when the visitor asks for works like one they have seen. One round is usually enough; there are at most two. Then answer with three " +
  "to five picks from the works the tools returned in this turn (fewer only if fewer fit, none only if nothing fits), best first, by id, each with why: one short factual " +
  "phrase in plain words on what it shows and its mood ('two doves, quiet and hopeful', 'an oil, calm sea under a low " +
  "grey sky'), from its technique and mood words, never a list of them. The page shows the title, artist, year, size and price " +
  "beside it: never mention those in why, and never translate a title. No praise, and nothing about an artist's style or " +
  "tradition beyond what the tools said. Never give a number of works in the reply -- not 'Found 68 " +
  "winter landscapes', not 'The search covers 127 works': the page shows the count under it. A price in the reply is one a tool gave, exactly. Return as the search the one your picks came from, so the page shows the rest of its works under " +
  "them. Name works, prices and facts only from what the tools returned in this turn, never from memory. Earlier turns " +
  "list the works shown with their ids; to say more about one of them, or find more like it, call similar with its id. " +
  "If what the visitor asked for is not there (nothing by that artist for sale, nothing near the budget), say so plainly " +
  "and pick the closest alternatives.\n\n";
const ASK_TAIL = "The reply: one or two short sentences, neutral and factual, like a catalogue's search desk. Say in plain words what the " +
  "search now covers; if one fact would narrow it most, ask for it in a direct question. No greetings, compliments, " +
  "exclamations, enthusiasm or small talk, and no remarks on the visitor's taste, room or plans (never 'How lovely', " +
  "'great choice', 'something that sings'), and do not announce that you are searching. Ask only when the answer would " +
  "change the search. As soon as there is anything to go on, even only a size or a budget, search (show: true). Set show to false only when there is nothing to search on yet or the visitor " +
  "is just saying thanks or goodbye; then answer in a few words and return the search unchanged. The one exception: when the visitor's first message is " +
  "only general praise with no subject, mood, medium, size, budget or artist ('something nice', 'beautiful', 'ilus kena tore'), they want to see works, so " +
  "show them: show: true, the search as the controls have it, no tools and no picks, and a reply that says these words do not narrow the search, this is " +
  "the general selection, and asks what subject or mood they would like. The reply is never empty.\n\n" +
  "The search, exact rather than broad:\n" +
  "- words: one to five from the list below, most important first, for the mood, light, colour, season and subject the " +
  "visitor asks for. Use their own words first; add a word for a room only when they give nothing else (a bedroom: " +
  "serene; an office: simple). Do not pad with loosely related words: two right words beat five vague ones.\n" +
  "- terms: when the visitor names a concrete subject a title would name (a place, a thing, an animal, a plant, a " +
  "season), up to eight short lowercase stems that would begin a word in such a title, in Estonian and in English: the " +
  "sea: meri, mere, sea; winter: talv, talve, winter; autumn: sügis, sügise, autumn; horses: hobu, horse; Tallinn: tallinn; birches: kask, kase, birch; a still life: natüürmort, " +
  "vaikelu, still life; a landscape: maastik, landscape; a portrait: portree, portrait. Only stems for what the visitor " +
  "named, not for the subjects it might include. Empty for moods, colours and styles.\n" +
  "- media: what the visitor asks for, any of 'oil', 'acrylic', 'watercolour', 'mixed' (mixed media, collage), 'print' " +
  "(etchings, lithographs, linocuts, screenprints, giclée), 'drawing' (pencil, ink, charcoal, pastel), 'sculpture', " +
  "'photo', and 'painting' (paintings in any medium: whenever they ask for a painting without naming its medium). " +
  "Empty for no preference.\n" +
  "- size: 'small' up to 40 cm (a shelf, a hallway, a gift), 'medium' 40-100 cm (above a desk, a bed, a dresser), " +
  "'large' over 100 cm (a living-room wall, above a sofa), 'any' if unknown.\n" +
  "- budget_min and budget_max in euros, 0 for none ('under 500': max 500; 'around 1000': 800 and 1200; 'not more than " +
  "two thousand': max 2000).\n" +
  "- artist: the artist's name in its basic form (Malle Leis, not Malle Leisi or Leisilt), only when the visitor asks " +
  "for works by a particular artist; else empty. Asking for an " +
  "artist starts a new search: keep only the medium and budget said in the same message, and clear size, words and terms.\n" +
  "Keep everything the controls and earlier turns set unless the visitor changes it; when they ask for something else " +
  "entirely, clear what no longer applies.\n\n" +
  "Prices, delivery, framing and how to buy are the gallery's: each work links to its page. Do not promise discounts, " +
  "availability or anything about a work's value as an investment. If asked something else, answer in one sentence and " +
  "return to the search. Words: " + WORDS.join(", ");
const SYSTEM_ASK = ASK_HEAD + BLIND + ASK_TAIL, SYSTEM_TOOLS = ASK_HEAD + LOOK + ASK_TAIL;

const MEDIA = ["oil", "acrylic", "watercolour", "mixed", "print", "drawing", "sculpture", "photo", "painting"];
const SCHEMA_ASK = {
  type: "object",
  properties: {
    reply: { type: "string" },
    show: { type: "boolean" },
    words: { type: "array", items: { type: "string", enum: WORDS } },
    terms: { type: "array", items: { type: "string" } },
    media: { type: "array", items: { type: "string", enum: MEDIA } },
    size: { type: "string", enum: ["any", "small", "medium", "large"] },
    budget_min: { type: "integer" },
    budget_max: { type: "integer" },
    artist: { type: "string" },
  },
  required: ["reply", "show", "words", "terms", "media", "size", "budget_min", "budget_max", "artist"],
  additionalProperties: false,
};

// the tools: search takes the same fields as the answer's search; the answer adds the picks
const ROUNDS = 2;                // tool rounds a turn, then Claude must answer (each round is ~4 s)
const FIELDS = ["words", "terms", "media", "size", "budget_min", "budget_max", "artist"];
const obj = (properties, required = Object.keys(properties)) => ({ type: "object", properties, required, additionalProperties: false });
const TOOLS = [
  { name: "search", strict: true, description: "Run a search over the works for sale, exactly as the page runs it. Returns how many " +
    "works match and the first ten not yet shown, best first: id, title, artist, year, technique, size in cm, asking price in " +
    "euros (null if on request), gallery, strongest mood words. by_artist_any_settings: when nothing matches a search with an " +
    "artist, how many of their works are for sale outside the other settings.",
    input_schema: obj(Object.fromEntries(FIELDS.map(k => [k, SCHEMA_ASK.properties[k]]))) },
  { name: "artist", strict: true, description: "One artist's record: works for sale and their asking-price range, how many works " +
    "the museums hold, the auction record (lots, sold, hammer prices: the middle half from four sales up, else lowest and " +
    "highest), and up to ten of their works for sale. Takes a name or part of one; several matches return did_you_mean.",
    input_schema: obj({ name: { type: "string" } }) },
  { name: "similar", strict: true, description: "The works for sale closest to one work (by its id) in mood and medium, up to " +
    "ten not yet shown; of: the work itself. budget_max in euros, 0 for none.",
    input_schema: obj({ id: { type: "string" }, budget_max: { type: "integer" } }) },
];
const SCHEMA_PICKS = JSON.parse(JSON.stringify(SCHEMA_ASK));
SCHEMA_PICKS.properties.picks = { type: "array", items: obj({ id: { type: "string" }, why: { type: "string" } }) };
SCHEMA_PICKS.required.push("picks");

// the conversation as the page sends it: user first, turns alternating, short
function conversation(body) {
  const m = Array.isArray(body && body.messages) ? body.messages.slice(-12) : [];
  const out = [];
  for (const x of m) {
    const role = x && x.role === "assistant" ? "assistant" : "user";
    const text = String((x && x.content) || "").replace(/\s+/g, " ").trim().slice(0, role === "user" ? 400 : 1400);
    if (!text) continue;
    if (out.length && out[out.length - 1].role === role) out[out.length - 1].content += " " + text;
    else out.push({ role, content: text });
  }
  while (out.length && out[0].role !== "user") out.shift();
  return out.length && out[out.length - 1].role === "user" ? out : [];
}

// Buy Art's replies come from Sonnet in both languages: side by side on 32 conversations (2026-11-05) Haiku 5.5 was
// seven times cheaper but lost a budget or a "bigger" on the way, and its Estonian had invented words. The mood page's
// word-picking stays on Haiku (MODEL). Thinking off (between_tools, Sonnet 5.5 only), low effort, and Anthropic's
// server-side fallback, which re-runs a mistaken safety decline on another model
const SONNET = "claude-sonnet-5-5";
// The message and its content blocks; null for a decline. After a fallback, only the blocks past the last
// "fallback" marker are the answer. extra: tools, tool_choice, cache_control
// Anthropic's reason for refusing a call ("credit balance is too low", a bad parameter), into the Worker's log: the
// page is told only the status. The key is in the headers, never in the answer
async function refused(r, where) {
  let e = {}; try { e = (await r.json()).error || {}; } catch (x) {}
  console.log("anthropic refused", where, r.status, String(e.type || ""), String(e.message || "").slice(0, 300));
}
async function call(env, system, messages, schema, max_tokens, model = MODEL, extra = {}) {
  const sonnet = model === SONNET;
  const headers = { "x-api-key": env.ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01", "content-type": "application/json" };
  const body = { model, max_tokens, system, messages, output_config: { format: { type: "json_schema", schema } }, ...extra };
  if (sonnet) {
    headers["anthropic-beta"] = "server-side-fallback-2026-07-01";
    Object.assign(body, { thinking: { type: "between_tools" }, fallbacks: "default" });
    body.output_config.effort = extra.tools ? "medium" : "low";    // at low it answered a quarter of the turns without searching
  }
  const r = await fetch("https://api.anthropic.com/v1/messages", { method: "POST", headers, body: JSON.stringify(body) });
  if (!r.ok) { await refused(r, model); throw new Error("The reader answered " + r.status + "."); }
  const m = await r.json();
  if (extra.tools) console.log("ask", model, m.stop_reason, JSON.stringify(m.usage || {}));
  if (m.stop_reason === "refusal") return null;
  const c = m.content || [], at = c.map(b => b.type).lastIndexOf("fallback");
  return { stop: m.stop_reason, content: c.slice(at + 1) };
}
const answer = content => JSON.parse(content.filter(b => b.type === "text").map(b => b.text).join(""));
async function claude(env, system, messages, schema, max_tokens, model = MODEL) {
  const m = await call(env, system, messages, schema, max_tokens, model);
  return m && answer(m.content);
}

// the turn's tool rounds so far, as the page sends them back: Claude's turns (unchanged, thinking blocks
// included: Sonnet needs them back as they were) and the page's results, alternating. Also the ids of
// every work the results named: the only works Claude may pick
async function trailOf(t, env, ip) {
  if (!Array.isArray(t) || t.length > 2 * ROUNDS || t.length % 2 || JSON.stringify(t).length > 200000) return null;
  const ids = new Set(), out = [];
  for (let i = 0; i < t.length; i++) {
    const m = t[i];
    if (!m || m.role !== (i % 2 ? "user" : "assistant")) return null;
    const c = i % 2 ? m.content : await unseal(env, ip, m.content);
    if (!Array.isArray(c) || !c.length) return null;
    if (i % 2 === 1) {
      if (!c.every(b => b && b.type === "tool_result" && typeof b.content === "string" && b.content.length <= 10000)) return null;
      for (const b of c) for (const x of b.content.matchAll(/"id":"(w\d+)"/g)) ids.add(x[1]);
    }
    out.push({ role: m.role, content: c });
  }
  return { t: out, ids };
}
// Claude's turns go to the page sealed (AES-GCM, the key made from ANTHROPIC_API_KEY) and come back the same way: the
// page can neither read them nor write its own, so the door runs this page's searches and is no open line to Claude.
// A seal is good for the visitor's address and ten minutes
const SEAL_TTL = 600;
const unb64u = s => Uint8Array.from(atob(s.replace(/-/g, "+").replace(/_/g, "/")), c => c.charCodeAt(0));
const sealKey = async env => crypto.subtle.importKey("raw", await crypto.subtle.digest("SHA-256", enc("trail|" + env.ANTHROPIC_API_KEY)), "AES-GCM", false, ["encrypt", "decrypt"]);
async function seal(env, ip, content) {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const c = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, await sealKey(env), enc(JSON.stringify({ ip, exp: Date.now() + SEAL_TTL * 1000, content })));
  return b64u(iv) + "." + b64u(c);
}
async function unseal(env, ip, s) {
  try {
    const [iv, c] = String(s).split(".");
    const x = JSON.parse(new TextDecoder().decode(await crypto.subtle.decrypt({ name: "AES-GCM", iv: unb64u(iv) }, await sealKey(env), unb64u(c))));
    return x.ip === ip && x.exp > Date.now() && Array.isArray(x.content) ? x.content : null;
  } catch (e) { return null; }
}

// the language of a message: its common words counted; letters like ä alone (an Estonian name in English) do not decide it
const ET = /(?<![\p{L}])(ja|ning|mis|midagi|kas|tahan|otsin|pilt|pildi|maal|maali|maale|seinale|seina|alla|umbes|kuni|tere|aitäh|väike|väikest|suur|suurt|tuppa|kingituseks|eurot?|on|ei|see|selle|mulle|mul|ma|mina|palun|näita|veel|rohkem|või|aga|kui|ka|tööd|teoseid|teos)(?![\p{L}])/giu;
const EN = /\b(the|a|an|for|and|or|something|anything|want|looking|painting|paintings|picture|print|prints|wall|under|around|about|hi|hello|thanks|room|gift|my|me|show|by|with|of|is|it|i|you|please|any|some|more|less|works?|like|can|do|have|what|which|from|to|in|on|no|yes|actually)\b/gi;
function langOf(text, page) {
  const et = (text.match(ET) || []).length + (/[õäöü]/i.test(text) ? 0.5 : 0), en = (text.match(EN) || []).length;
  return et > en ? "et" : en > et ? "en" : page === "et" ? "et" : "en";
}

// a search as one string, to tell whether a turn changed it
const key = q => JSON.stringify([[...q.media].sort(), q.words, [...q.terms].sort(), q.lo, q.hi, q.size, q.artist.toLowerCase()]);
// the page's controls as the visitor left them, read defensively: they arrive from the browser
const int = v => Math.max(0, Math.min(10000000, Math.round(Number(v) || 0)));
const short = (v, n) => String(v || "").replace(/\s+/g, " ").trim().slice(0, n);
function controls(f) {
  f = f && typeof f === "object" ? f : {};
  const list = (v, ok) => Array.isArray(v) ? [...new Set(v.map(x => short(x, 30)).filter(ok))].slice(0, 8) : [];
  const media = list(f.media, x => MEDIA.includes(x)), words = list(f.words, x => WORDS.includes(x)), terms = list(f.terms, x => x);
  const lo = int(f.min), hi = int(f.max), size = ["small", "medium", "large"].includes(f.size) ? f.size : "any";
  const price = lo && hi ? "€" + lo + "–" + hi : hi ? "up to €" + hi : lo ? "from €" + lo : "any";
  const artist = short(f.artist, 60);
  return { key: key({ media, words, terms, lo, hi, size, artist }), text: "The page's controls are now set to: medium: " + (media.join(", ") || "any") + "; price: " + price + "; size: " + size +
    "; words: " + (words.join(", ") || "none") + "; title terms: " + (terms.join(", ") || "none") + "; artist: " +
    (artist || "none") + ". This is the visitor's current search: start from it." };
}

// My List: the works the visitor saved while browsing (the page sends the latest twelve it can name: title, artist,
// and the id of one for sale), a taste to go on when they point to it or ask with nothing else to go on
function mylist(v) {
  const L = Array.isArray(v) ? v.slice(0, 12).map(x => x && typeof x === "object" ? { t: short(x.t, 80), a: short(x.a, 60), id: /^w\d{1,6}$/.test(x.id || "") ? x.id : "" } : null).filter(x => x && x.a) : [];
  if (!L.length) return "";
  return "\n\nThe visitor's My List, the works they saved while browsing (museum works, and works for sale where an id is given): " +
    L.map(x => `"${x.t}" by ${x.a}${x.id ? " (" + x.id + ")" : ""}`).join("; ") + ". Use it when they point to it ('like the ones I " +
    "saved', 'my taste') or ask with nothing else to go on: their artists, the media and moods those works suggest, and similar on " +
    "a saved work's id. Otherwise leave it aside, and never list it back to them.";
}

async function ask(body, env, reply, ip) {
  const messages = conversation(body);
  if (!messages.length) return reply({ error: "Nothing to read." }, 400);
  let out;
  // the reply's language is decided here, not left to the model (it drifted): the visitor's last
  // message if it reads as one language, else the page's
  const et = langOf(messages[messages.length - 1].content, body.lang) === "et";
  const was = controls(body.filters);
  // a page that runs the tools: Claude looks before it answers. Steps sent on any
  // other turn are refused: the doors above counted that turn as a free later round only if it was a search turn
  if (!body.tools && Array.isArray(body.trail) && body.trail.length) return reply({ error: "Unreadable search steps." }, 400);
  const trail = body.tools ? await trailOf(body.trail || [], env, ip) : null;
  if (body.tools && !trail) return reply({ error: "Unreadable search steps." }, 400);
  const system = (trail ? SYSTEM_TOOLS : SYSTEM_ASK) + "\n\n" + was.text + mylist(body.mylist) + "\n\n" + (et
    ? "Reply in Estonian: plain, neutral, matter-of-fact Estonian, addressing the visitor as 'sina'; no exclamations or compliments."
    : "Reply in English.");
  const none = { reply: "", show: false, words: [], terms: [], media: [], kind: "any", size: "any", budget_min: 0, budget_max: 0, artist: "" };
  try {
    if (trail) {
      // the same system, tools and messages every round, with the rounds appended: the cache and Sonnet's
      // thinking blocks hold. After the last round the tools stay listed but cannot be called
      const m = await call(env, system, messages.concat(trail.t), SCHEMA_PICKS, 1500, SONNET,
        { tools: TOOLS, tool_choice: { type: trail.t.length / 2 >= ROUNDS ? "none" : "auto" }, cache_control: { type: "ephemeral" } });
      if (!m) return reply(none);
      const calls = m.content.filter(b => b.type === "tool_use");
      if (m.stop === "tool_use" && calls.length) return reply({ calls: calls.map(b => ({ id: b.id, name: b.name, input: b.input })), content: await seal(env, ip, m.content) });
      out = answer(m.content);
      // an answer with no reply (seen once, Sonnet, no search made): the one-call answer instead
      if (!String(out.reply || "").trim()) out = await claude(env, system.replace(SYSTEM_TOOLS, SYSTEM_ASK), messages, SCHEMA_ASK, 800, SONNET);
    } else out = await claude(env, system, messages, SCHEMA_ASK, 800, SONNET);
  }
  catch (e) { console.log("ask failed", String(e.message)); return reply({ error: String(e.message || "The assistant could not be reached.") }, 502); }
  if (!out) return reply(none);
  const media = [...new Set((out.media || []).filter(m => MEDIA.includes(m)))];
  // kind: what the page before the controls read (one medium, else any)
  const kind = media.length === 1 ? { oil: "paint", acrylic: "paint", painting: "paint", watercolour: "paper", mixed: "any", print: "paper", drawing: "paper", sculpture: "sculpture", photo: "photo" }[media[0]] : "any";
  const size = ["small", "medium", "large"].includes(out.size) ? out.size : "any", lo = int(out.budget_min), hi = int(out.budget_max);
  const words = [...new Set((out.words || []).filter(w => WORDS.includes(w)))].slice(0, 5);
  const terms = [...new Set((out.terms || []).map(t => short(t, 30).toLowerCase()).filter(t => t.length >= 3))].slice(0, 8);
  const artist = short(out.artist, 60);
  // a turn that changes the search shows what it finds: the model tended to ask its question first and show nothing.
  // A search emptied by a turn that shows nothing ("thanks") is a slip, not a change: the page keeps its controls
  const now = key({ media, words, terms, lo, hi, size, artist }), empty = now === key({ media: [], words: [], terms: [], lo: 0, hi: 0, size: "any", artist: "" });
  // picks: only works the tools returned this turn, each once
  const picks = [];
  for (const p of trail && Array.isArray(out.picks) ? out.picks : [])
    if (p && trail.ids.has(p.id) && !picks.some(x => x.id === p.id) && picks.length < 5) picks.push({ id: p.id, why: short(p.why, 200) });
  const show = !!out.show && !(empty && !String(out.reply || "").trim()) || (now !== was.key && !empty) || picks.length > 0;
  return reply({
    ...(trail ? { picks } : {}),
    reply: String(out.reply || "").slice(0, 600),
    show, words, terms, media, kind, artist, size, budget_min: lo, budget_max: hi,
  });
}

// My List across devices: a visitor signs in with their email address and the list follows them. POST /list/login
// sends a sign-in link; /list/verify trades the link's token for a session; /list/sync, /list/logout and
// /list/delete use the session. In KV (binding LISTS), every key a hash: t:<token's hash> the address and its account
// for 15 minutes; s:<session's hash> the account, for a year; u:<account> the list and the account's address (the
// sign-in says so), two years from its last change, with the address, the day it began and the list's length also
// in the key's metadata for the backoffice; r:<inbox> and r:<inbox>:<visitor> sign-in links sent this hour, both HMACs. The account is an HMAC of the
// address (LIST_SECRET); accounts from before 15 Oct 2026 kept no address and get it at their next sign-in. If the
// visitor ticked "Email me about new features", n:<account> keeps the address, the time they confirmed it by opening the
// link, and the unsubscribe link every such email must carry, until they stop it (/list/unsubscribe with that link's
// token, or /list/news signed in) or delete the account. Sale alerts, the same way: w:<account> keeps the address,
// the language and the alerts' own unsubscribe link while "Email me when my artists come up for sale" is on
// (/list/alerts, signed in); /alerts/send mails each of them what is new by the artists on their list. worker/README.md says how to read them out. Needs the KV
// binding LISTS and the secrets LIST_SECRET and RESEND_API_KEY (worker/README.md); MAIL_FROM optional.
const LINK_TTL = 15 * 60, SESSION_TTL = 365 * 86400, LIST_TTL = 2 * 365 * 86400, LIST_MAX = 1000, LINKS_PER_HOUR = 4;
// sign-in links: 4 an hour to an inbox from one visitor, 10 an hour to it from everyone, and MAIL_PER_DAY a day in all,
// under Resend's free 100, so neither one inbox nor the sending quota can be flooded through the door
const LINKS_PER_INBOX = 10, MAIL_PER_DAY = 90;
// the inbox an address lands in: a "+tag" dropped, and Gmail's dots, so name+1@ and n.a.m.e@ count as one inbox
function inbox(email) {
  let [l, d] = email.split("@");
  l = l.split("+")[0];
  if (d === "gmail.com" || d === "googlemail.com") { l = l.replace(/\./g, ""); d = "gmail.com"; }
  return l + "@" + d;
}
const enc = s => new TextEncoder().encode(s);
const b64u = b => { let s = ""; for (const x of new Uint8Array(b)) s += String.fromCharCode(x); return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, ""); };
const token = () => b64u(crypto.getRandomValues(new Uint8Array(24)));
const hash = async s => b64u(await crypto.subtle.digest("SHA-256", enc(s)));
async function account(env, email) {
  const k = await crypto.subtle.importKey("raw", enc(env.LIST_SECRET), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  return b64u(await crypto.subtle.sign("HMAC", k, enc(email)));
}
const EMAIL = /^[^\s@<>()[\]",;:\\]{1,64}@[a-z0-9-]+(\.[a-z0-9-]+)*\.[a-z]{2,}$/;
const workKey = k => typeof k === "string" && k.length > 0 && k.length <= 120 && !/[\u0000-\u001f]/.test(k);
const keys = v => Array.isArray(v) ? [...new Set(v.filter(workKey))].slice(0, LIST_MAX) : [];
const putList = (KV, u, rec) => KV.put("u:" + u, JSON.stringify(rec),
  { expirationTtl: LIST_TTL, metadata: { e: rec.e, since: rec.since, n: rec.items.length, at: rec.updated } });

const MAIL = {          // no bare "museaal.ee" in the text: mail apps make it a second link next to the sign-in one
  en: { subject: "Your sign-in link for museaal.ee", text: (link, news) => "Here is your link to sign in to Museaal:\n\n" + link +
    "\n\nIt works once, for 15 minutes. To use your list on another device, ask for a new link there.\n\n" + (news ?
    "Once you sign in, we will also email you now and then about new features. You can unsubscribe any time.\n\n" : "") +
    "If you did not ask to sign in, you can ignore this email." },
  et: { subject: "Sinu sisselogimislink museaal.ee-sse", text: (link, news) => "Siin on sinu link, et logida sisse Museaali:\n\n" + link +
    "\n\nLink töötab üks kord ja 15 minutit. Teises seadmes nimekirja kasutamiseks küsi seal uus link.\n\n" + (news ?
    "Kui oled sisse loginud, saadame sulle aeg-ajalt kirja museaal.ee uuendustest. Tellimuse saad lõpetada igal ajal.\n\n" : "") +
    "Kui sa sisselogimist ei küsinud, võid selle kirja tähelepanuta jätta." },
};
async function mail(env, to, m) {
  if (env.SEND_MAIL) return env.SEND_MAIL({ to, ...m });          // the local test server (.dev/serve.mjs) prints it instead
  const r = await fetch("https://api.resend.com/emails", {
    method: "POST", headers: { Authorization: "Bearer " + env.RESEND_API_KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ from: env.MAIL_FROM || "museaal.ee <list@museaal.ee>", to: [to], reply_to: "info@museaal.ee", ...m }),
  });
  if (!r.ok) throw new Error("mail " + r.status);
}

// the link that stops the news emails: the account and a seal on it, so nobody can stop someone else's
// ...and the one that stops the sale alerts, sealed apart, so neither link stops the other
const unsubLink = async (env, u, lang, alert) => (env.SITE || "https://museaal.ee/") + "#lang=" + lang + (alert ? "&unsuba=" : "&unsub=") + u + "."
  + await mac(env.LIST_SECRET, (alert ? "unsub-alerts|" : "unsub|") + u);
// the day counters, c:<what>:<day>: questions to /ask (a turn, not its tool rounds) and their rounds, readings on the
// mood page, sign-in mails, new accounts. Two of them are caps on what the Anthropic key and the mail quota spend.
// With a D1 database bound as COUNTS (worker/README.md) a count is one step in it, "add one and say how many", so a
// burst of requests at once cannot all read the same figure and slip past a cap, and KV's writes are left to the lists.
// Without it, KV as before: a read and a write, so requests at once can share one count; kept 400 days.
const DAY_TTL = 400 * 86400;
const today = () => new Date().toISOString().slice(0, 10);
let table = null;
const ready = env => table || (table = env.COUNTS.prepare("CREATE TABLE IF NOT EXISTS counts (k TEXT PRIMARY KEY, n INTEGER NOT NULL)").run()
  .catch(e => { table = null; throw e; }));
// D1 that fails is logged and the count goes to KV instead, so trouble with the database does not close the assistant
// (that day's figure is then split between the two, and the cap counts only what each has)
async function bump(env, what, by = 1) {          // -> the day's count, this one included
  const k = "c:" + what + ":" + today();
  if (env.COUNTS) {
    try {
      await ready(env);
      const r = await env.COUNTS.prepare("INSERT INTO counts (k, n) VALUES (?1, ?2) ON CONFLICT(k) DO UPDATE SET n = n + ?2 RETURNING n").bind(k, by).first();
      return r.n;
    } catch (e) { console.log("D1 count failed, counted in KV", String(e.message)); }
  }
  if (!env.LISTS) return 0;
  const n = (+(await env.LISTS.get(k)) || 0) + by;
  await env.LISTS.put(k, String(n), { expirationTtl: DAY_TTL });
  return n;
}
async function counted(env, what, day) {          // a day's count, for the backoffice
  const k = "c:" + what + ":" + day;
  let d = 0;
  if (env.COUNTS) try { await ready(env); const r = await env.COUNTS.prepare("SELECT n FROM counts WHERE k = ?1").bind(k).first(); d = r ? r.n : 0; }
  catch (e) { console.log("D1 read failed", String(e.message)); }
  return d + (env.LISTS ? +(await env.LISTS.get(k)) || 0 : 0);     // with D1, KV holds only what fell back to it
}
const later = (ctx, p) => { p = p.catch(e => console.log("count failed", String(e.message))); if (ctx && ctx.waitUntil) ctx.waitUntil(p); };

const logins = new Map();        // visitor -> times of their recent sign-in requests: 5 in ten minutes
async function list(path, body, env, reply, ip) {
  const KV = env.LISTS;
  if (!KV || !env.LIST_SECRET) return reply({ error: "Lists are not set up." }, 503);
  if (path === "login") {
    const email = String(body.email || "").trim().toLowerCase(), lang = body.lang === "et" ? "et" : "en";
    if (email.length > 254 || !EMAIL.test(email)) return reply({ error: "bad email" }, 400);
    if (!env.RESEND_API_KEY && !env.SEND_MAIL) return reply({ error: "Mail is not set up." }, 503);
    if (tooMany(ip, logins, 5, 600000)) return reply({ error: "Too many requests; wait a few minutes." }, 429);
    // each sign-in link is an email sent: like the doors that call Claude, only for a visitor who passed Turnstile, and
    // here with a token of its own each time, not the half-hour pass the other doors take (the page always sends one)
    if (env.TURNSTILE_SECRET && await human({ human: body.human }, env, ip) === null) return reply({ error: "Please confirm you are not a robot.", human: true }, 401);
    const u = await account(env, email), box = "r:" + await mac(env.LIST_SECRET, "inbox|" + inbox(email)), mine = box + ":" + await mac(env.LIST_SECRET, "ip|" + ip);   // keyed: no address can be read back from it
    const [sent, own] = await Promise.all([KV.get(box), KV.get(mine)]).then(v => v.map(x => +x || 0));
    if (own >= LINKS_PER_HOUR || sent >= LINKS_PER_INBOX) return reply({ error: "Too many links for this address; wait an hour." }, 429);
    if (await bump(env, "mail") > MAIL_PER_DAY) return reply({ error: "No more sign-in links can be sent today; try again tomorrow." }, 429);
    const t = token();
    await Promise.all([KV.put(box, String(sent + 1), { expirationTtl: 3600 }), KV.put(mine, String(own + 1), { expirationTtl: 3600 })]);
    const news = body.news === true;
    // n: the secret the asking browser kept (list-sync.js), so verify can tell that browser from any other
    const nonce = typeof body.nonce === "string" ? body.nonce.slice(0, 64) : "";
    await KV.put("t:" + await hash(t), JSON.stringify({ u, e: email, lang, news, ...(nonce ? { n: await hash(nonce) } : {}) }), { expirationTtl: LINK_TTL });
    // the token after the #, which browsers never send: it reaches no server's logs, ours or GitHub's
    const link = (env.SITE || "https://museaal.ee/") + "#lang=" + lang + "&list=mine&login=" + t;
    try { await mail(env, email, { subject: MAIL[lang].subject, text: MAIL[lang].text(link, news) }); }
    catch (e) { console.log("list mail failed", String(e.message)); return reply({ error: "The email could not be sent." }, 502); }
    return reply({ ok: true });
  }
  if (path === "verify") {
    const k = "t:" + await hash(String(body.token || "").slice(0, 64)), t = await KV.get(k, "json");
    if (!t) return reply({ error: "This link has expired or was used." }, 410);
    await KV.delete(k);
    const rec = await KV.get("u:" + t.u, "json");
    if (!rec) await bump(env, "signup").catch(() => {});
    // born: when the account began, so a session from before it was deleted and made again is no longer good (below)
    if (!rec || rec.e !== t.e) await putList(KV, t.u, { items: [], updated: Date.now(), ...(rec ? {} : { born: Date.now() }), ...rec, e: t.e, since: rec ? rec.since : today() });
    const s = token();
    await KV.put("s:" + await hash(s), JSON.stringify({ u: t.u, at: Date.now() }), { expirationTtl: SESSION_TTL });
    // the box was ticked and the link opened: the address is confirmed, and kept for the news emails
    if (t.news) await KV.put("n:" + t.u, JSON.stringify({ e: t.e, lang: t.lang || "en", at: new Date().toISOString(), v: 1, unsub: await unsubLink(env, t.u, t.lang || "en") }));
    // bound: opened in the browser that asked for the link. Anywhere else the page asks the visitor first, as a link
    // sent on by someone else would otherwise sign them in to that person's account and hand it their list
    const bound = !!t.n && typeof body.nonce === "string" && t.n === await hash(body.nonce.slice(0, 64));
    return reply({ session: s, email: t.e, items: rec ? rec.items : [], news: !!(t.news || await KV.get("n:" + t.u)), alerts: !!(await KV.get("w:" + t.u)), bound });
  }
  if (path === "unsubscribe") {
    const [u, seal] = String(body.token || "").slice(0, 200).split("."), alert = body.what === "alerts";
    if (!u || !seal || seal !== await mac(env.LIST_SECRET, (alert ? "unsub-alerts|" : "unsub|") + u)) return reply({ error: "This link is not valid." }, 400);
    await KV.delete((alert ? "w:" : "n:") + u);
    return reply({ ok: true });
  }
  const sk = "s:" + await hash(String(body.session || "").slice(0, 64)), s = await KV.get(sk, "json");
  if (!s) return reply({ error: "Signed out." }, 401);
  if (path === "logout") { await KV.delete(sk); return reply({ ok: true }); }
  // the account as it is now: gone (deleted from another device), or begun again after this session was made, signs it out
  const rec = await KV.get("u:" + s.u, "json");
  if (!rec || rec.born && !(s.at >= rec.born)) { await KV.delete(sk); return path === "delete" ? reply({ ok: true }) : reply({ error: "Signed out." }, 401); }
  if (path === "delete") { await Promise.all(["u:", "n:", "w:"].map(p => KV.delete(p + s.u))); await KV.delete(sk); return reply({ ok: true }); }
  // signed in: the news emails on or off. The session came from a link opened in this address's inbox, so turning
  // them on needs no second link; the address is checked against the account, so a session can't add another one
  if (path === "news") {
    if (body.on !== true) { await KV.delete("n:" + s.u); return reply({ ok: true }); }
    const email = String(body.email || "").trim().toLowerCase().slice(0, 254), lang = body.lang === "et" ? "et" : "en";
    if (await account(env, email) !== s.u) return reply({ error: "Not this account's address." }, 403);
    await KV.put("n:" + s.u, JSON.stringify({ e: email, lang, at: new Date().toISOString(), v: 1, unsub: await unsubLink(env, s.u, lang) }));
    return reply({ ok: true });
  }
  // ...and the sale alerts, on or off, the same way
  if (path === "alerts") {
    if (body.on !== true) { await KV.delete("w:" + s.u); return reply({ ok: true }); }
    const email = String(body.email || "").trim().toLowerCase().slice(0, 254), lang = body.lang === "et" ? "et" : "en";
    if (await account(env, email) !== s.u) return reply({ error: "Not this account's address." }, 403);
    await KV.put("w:" + s.u, JSON.stringify({ e: email, lang, at: new Date().toISOString(), unsub: await unsubLink(env, s.u, lang, true) }));
    return reply({ ok: true });
  }
  if (path !== "sync") return reply({ error: "No such thing." }, 404);
  // the browser sends what it added and removed since the two last agreed, and takes the result back
  const was = JSON.stringify(rec.items), rem = new Set(keys(body.remove));
  const items = rec.items.filter(k => !rem.has(k));
  for (const k of keys(body.add)) if (!items.includes(k) && items.length < LIST_MAX) items.push(k);
  if (JSON.stringify(items) !== was) await putList(KV, s.u, { ...rec, items, updated: Date.now() });
  const [news, alerts] = await Promise.all([KV.get("n:" + s.u), KV.get("w:" + s.u)]);
  return reply({ items, news: !!news, alerts: !!alerts });
}

const seen = new Map(), rounds = new Map(), syncs = new Map();   // visitor -> times of their recent searches; of all their requests; of list requests
function tooMany(ip, map = seen, limit = PER_MINUTE, span = 60000) {
  const now = Date.now(), t = (map.get(ip) || []).filter(x => now - x < span);
  t.push(now); map.set(ip, t);
  if (map.size > 5000) map.clear();
  return t.length > limit;
}

// Cloudflare Turnstile. The Origin header keeps other sites' pages out, but a script sets it as it likes; the widget's
// token cannot be forged. A token is good once and for five minutes, so the first one buys a pass: its expiry and an
// HMAC of the visitor's address and that expiry, sent back with every later message. A new address asks again.
const PASS_TTL = 30 * 60;
// /admin/stats, for museaal.ee/admin: the KV's keys counted by kind, the accounts' addresses, the day counters for 30 days, and GoatCounter's
// figures for the same days fetched with GOATCOUNTER_TOKEN (read-only), all behind ADMIN_KEY. KV list calls are
// a thousand keys each, and the free plan has a thousand a day: fine for a page opened now and then.
const tries = new Map();          // visitor -> wrong keys: 5 a minute
async function allKeys(KV, prefix) {
  const out = []; let cursor;
  do { const r = await KV.list({ prefix, cursor }); out.push(...r.keys); cursor = r.list_complete ? null : r.cursor; } while (cursor);
  return out;
}
async function goat(env, start, end) {
  if (!env.GOATCOUNTER_TOKEN) return null;
  const q = "start=" + start + "T00:00:00Z&end=" + end + "T23:59:59Z";
  const get = async p => {
    const r = await fetch("https://museaal.goatcounter.com/api/v0/" + p, { headers: { Authorization: "Bearer " + env.GOATCOUNTER_TOKEN, "Content-Type": "application/json" } });
    if (!r.ok) throw new Error("goatcounter " + r.status);
    return r.json();
  };
  const [total, hits, refs] = await Promise.all([get("stats/total?" + q), get("stats/hits?" + q + "&limit=100&group=day"), get("stats/toprefs?" + q + "&limit=15")]);
  const day = s => (s || []).map(x => [x.day, x.daily]);
  const all = (hits.hits || []).map(h => ({ path: h.path, title: h.title, event: !!h.event, count: h.count, days: day(h.stats) }));
  return { total: total.total, events: total.total_events, days: day(total.stats),
    pages: all.filter(h => !h.event).slice(0, 15).map(h => [h.path, h.count]),
    events_list: all.filter(h => h.event), refs: (refs.stats || []).map(r => [r.name || "(direct)", r.count]) };
}
async function admin(body, env, reply, ip) {
  if (!env.ADMIN_KEY) return reply({ error: "The backoffice is not set up." }, 503);
  if (tooMany(ip, tries, 5)) return reply({ error: "Too many tries; wait a minute." }, 429);
  if (await hash(String(body.key || "")) !== await hash(env.ADMIN_KEY)) return reply({ error: "Wrong key." }, 401);
  tries.delete(ip);
  const KV = env.LISTS, end = today(), days = [];
  for (let i = 29; i >= 0; i--) days.push(new Date(Date.now() - i * 86400000).toISOString().slice(0, 10));
  const out = { days, at: new Date().toISOString() };
  if (KV) {
    const [accounts, news, devices, links, alerts] = await Promise.all(["u:", "n:", "s:", "t:", "w:"].map(p => allKeys(KV, p)));
    out.keys = { accounts: accounts.length, news: news.length, devices: devices.length, links: links.length, alerts: alerts.length };
    // the accounts' addresses, newest first: [address or null (from before 15 Oct 2026), began, works, last change, news]
    const wantNews = new Set(news.map(k => k.name.slice(2)));
    out.people = accounts.map(k => { const m = k.metadata || {}; return [m.e || null, m.since || null, m.n ?? null, m.at || null, wantNews.has(k.name.slice(2))]; })
      .sort((a, b) => (b[1] || "").localeCompare(a[1] || "") || (b[3] || 0) - (a[3] || 0));
    for (const what of ["signup", "ask", "mood"]) out[what] = await Promise.all(days.map(d => counted(env, what, d)));
  }
  try { out.goat = await goat(env, days[0], end); } catch (e) { out.goat_error = String(e.message); }
  return reply(out);
}

// /alerts/send, from the deploy (.github/workflows/pages.yml, build_alerts.py), behind ALERT_KEY: the works that came
// up for sale since the live site was last built -- new gallery stock and new auction lots -- by artist slug, and to
// every account with the alerts on (w:) one email with those by the artists on its list. x:alerted keeps what was
// already announced (by its address, 120 days), so a deploy run again announces nothing twice. Alerts take at most
// ALERTS_PER_DAY of the day's MAIL_PER_DAY, so sign-in links always have room; Resend's batch call sends them a hundred at a time.
const ALERTS_PER_DAY = 60, ALERTED_DAYS = 120;
const ALERT_MAIL = {
  en: { brand: "Estonian Art Catalogue", eyebrow: "Sale alert", head: "New for sale from your artists", fresh: n => n + " new",
    count: (w, a) => w + (w === 1 ? " work" : " works") + " by " + a + (a === 1 ? " artist" : " artists"),
    subject: names => "For sale now: " + names, intro: "New on the market from the artists you saved on Museaal:",
    lot: (h, d) => "auction, " + h + (d ? ", " + d : ""), start: "starting price", all: "Your artists on Museaal:",
    why: "You get this because you turned on sale alerts for the artists on your list.", stop: "To stop them:", more: n => " and " + n + " more" },
  et: { brand: "Eesti Kunstikataloog", eyebrow: "Müügiteade", head: "Uut müügil sinu kunstnikelt", fresh: n => n + (n === 1 ? " uus" : " uut"),
    count: (w, a) => w + (w === 1 ? " teos" : " teost") + ", " + a + (a === 1 ? " kunstnik" : " kunstnikku"),
    subject: names => "Nüüd müügil: " + names, intro: "Uut turul kunstnikelt, kelle oled Museaalis salvestanud:",
    lot: (h, d) => "oksjon, " + h + (d ? ", " + d : ""), start: "alghind", all: "Sinu kunstnikud Museaalis:",
    why: "Saad selle kirja, sest lülitasid sisse teated oma nimekirja kunstnike müügitööde kohta.", stop: "Loobumiseks:", more: n => " ja veel " + n },
};
const euro = n => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, " ") + " €";
const htm = s => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const mailLink = (url, words, style) => '<a href="' + htm(url) + '" style="' + style + '">' + htm(words) + "</a>";
// The site's look, written out inline because mail apps drop most stylesheets: its colours and square corners, and its
// fonts where the reader has them, else the nearest system ones. Nothing is loaded from anywhere, so nothing tracks an open.
const MS = { ink: "#0B0C0E", soft: "#33363B", grey: "#6C7178", rule: "#DDDDDB", paper: "#FCFCFB", shop: "#F1F1F0",
  serif: "font-family:Newsreader,Georgia,'Times New Roman',serif;font-weight:500;", mono: "font-family:'IBM Plex Mono',Menlo,Consolas,monospace;", sans: "font-family:Archivo,Arial,Helvetica,sans-serif;" };
const MS_LABEL = MS.mono + "font-size:11px;line-height:1.5;letter-spacing:.1em;text-transform:uppercase;color:" + MS.grey + ";";
const MS_LINK = "color:" + MS.ink + ";text-decoration:underline;";
// Two versions of one email: designed HTML, where a work's title is its link, and plain text with the addresses written out.
function alertMail(lang, found, site, unsub) {
  const M = ALERT_MAIL[lang] || ALERT_MAIL.en, names = found.map(f => f.n);
  const head = names.slice(0, 3).join(", ") + (names.length > 3 ? M.more(names.length - 3) : "");
  const mine = site + "#lang=" + lang + "&list=mine&lt=artists";
  const lines = [M.intro, ""], cards = [];
  // Gmail cuts an email off at about 102 KB, and with it the way to unsubscribe: at most 18 artists and 36 works a mail, the rest behind My Artists
  const shown = found.slice(0, 18), room = Math.max(2, Math.min(12, Math.floor(36 / shown.length)));
  for (const f of shown) {
    let rows = "";
    lines.push(f.n.toUpperCase());
    f.w.slice(0, room).forEach(([, t, p, k, where, d, url, pic], i) => {
      const price = p ? (k === "l" ? M.start + " " + euro(p) : euro(p)) : "", at = k === "l" ? M.lot(where, d) : where;
      const rest = [price, at].filter(Boolean).join(" · "), edge = i ? "border-top:1px solid " + MS.rule + ";" : "";
      lines.push("  " + (t || "?") + (rest ? " · " + rest : ""), "  " + url);
      // the seller's own picture by its address, uncropped, as on the site
      rows += "<tr>" + (pic ? '<td width="96" style="' + edge + 'width:96px;padding:14px 14px 14px 0;vertical-align:top"><a href="' + htm(url) + '"><img src="' + htm(pic) + '" alt="' + htm(t) + '" width="96" style="display:block;width:96px;height:auto;border:0;background:#F3F3F2"></a></td>' : "") +
        "<td" + (pic ? "" : ' colspan="2"') + ' style="' + edge + 'padding:12px 0 14px;vertical-align:top">' + mailLink(url, t || "?", MS.serif + "font-size:18px;line-height:1.3;" + MS_LINK) +
        (price ? '<div style="' + MS.mono + "font-size:13px;line-height:1.4;color:" + MS.ink + ';padding-top:5px">' + htm(price.replace(/(\d) (?=[\d€])/g, "$1 ")) + "</div>" : "") +
        (at ? '<div style="' + MS_LABEL + 'padding-top:3px">' + htm(at) + "</div>" : "") + "</td></tr>";
    });
    if (f.w.length > room) {
      const more = M.more(f.w.length - room).trim();
      lines.push("  " + more);
      rows += '<tr><td colspan="2" style="border-top:1px solid ' + MS.rule + ';padding:12px 0 2px">' + mailLink(mine, more, MS_LABEL + "text-decoration:underline;") + "</td></tr>";
    }
    lines.push("");
    cards.push('<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid ' + MS.rule + ";border-collapse:separate;margin:0 0 16px;background:" + MS.paper + '"><tr><td style="padding:20px 22px 12px">' +
      '<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="' + MS.serif + "font-size:24px;line-height:1.15;color:" + MS.ink + ';padding-bottom:8px">' + htm(f.n) + '</td><td align="right" style="' + MS_LABEL + 'white-space:nowrap;padding:6px 0 8px 12px">' + htm(M.fresh(f.w.length)) + "</td></tr></table>" +
      '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid ' + MS.ink + '">' + rows + "</table></td></tr></table>");
  }
  if (found.length > shown.length) {
    const more = M.more(found.length - shown.length).trim();
    lines.push(more, "");
    cards.push('<div style="padding:2px 0 6px">' + mailLink(mine, more, MS_LABEL + "text-decoration:underline;") + "</div>");
  }
  lines.push(M.all + " " + mine, "", M.why + " " + M.stop, unsub);
  const works = found.reduce((s, f) => s + f.w.length, 0), brand = site.replace(/^https?:\/\/|\/$/g, "");
  const html = '<!doctype html><html lang="' + (lang === "et" ? "et" : "en") + '"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>' + htm(M.head) + "</title></head>" +
    '<body style="margin:0;padding:0;background:' + MS.paper + '"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:' + MS.paper + '"><tr><td align="center" style="padding:28px 16px 36px">' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;' + MS.sans + "color:" + MS.ink + '"><tr><td>' +
    '<div style="padding-bottom:22px">' + mailLink(site + "#lang=" + lang, M.brand, MS.serif + "font-size:26px;line-height:1.1;letter-spacing:-.01em;color:" + MS.ink + ";text-decoration:none;") + "</div>" +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:' + MS.shop + ";border-top:2px solid " + MS.ink + ';margin:0 0 22px"><tr><td style="padding:26px 22px 24px">' +
      '<div style="' + MS_LABEL + 'padding-bottom:10px">' + htm(M.eyebrow) + "</div>" +
      '<div style="' + MS.serif + "font-size:36px;line-height:1.08;letter-spacing:-.015em;color:" + MS.ink + '">' + htm(M.head) + "</div>" +
      '<div style="' + MS.mono + "font-size:12px;letter-spacing:.05em;color:" + MS.soft + ';padding-top:14px">' + htm(M.count(works, found.length)) + "</div></td></tr></table>" +
    cards.join("") +
    '<table role="presentation" cellpadding="0" cellspacing="0" style="margin:22px 0 28px"><tr><td style="background:' + MS.ink + '">' +
      mailLink(mine, M.all.replace(/:$/, ""), "display:inline-block;padding:13px 20px;" + MS.mono + "font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:" + MS.paper + ";text-decoration:none;") + "</td></tr></table>" +
    '<div style="border-top:1px solid ' + MS.rule + ";padding-top:14px;font-size:12px;line-height:1.6;color:" + MS.grey + '">' + htm(M.why) + " " + mailLink(unsub, M.stop.replace(/:$/, ""), "color:" + MS.grey + ";text-decoration:underline;") + '<div style="' + MS_LABEL + 'padding-top:10px">' + htm(brand) + "</div></div>" +
    "</td></tr></table></td></tr></table></body></html>";
  return { subject: M.subject(head), text: lines.join("\n"), html };
}
async function alerts(body, env, reply, ip) {
  if (!env.ALERT_KEY || !env.LISTS) return reply({ error: "Alerts are not set up." }, 503);
  if (tooMany(ip, tries, 5)) return reply({ error: "Too many tries; wait a minute." }, 429);     // wrong keys, as at the backoffice's door
  if (await hash(String(body.key || "")) !== await hash(env.ALERT_KEY)) return reply({ error: "Wrong key." }, 401);
  tries.delete(ip);
  const KV = env.LISTS, day = Math.floor(Date.now() / 864e5), site = env.SITE || "https://museaal.ee/";
  // {slug: {n: name, w: [[address, title, price, "s"|"l", gallery or house, date, link, picture]]}}, the addresses not yet announced
  const done = (await KV.get("x:alerted", "json")) || {}, fresh = new Map();
  for (const [slug, a] of Object.entries(body.items && typeof body.items === "object" ? body.items : {}).slice(0, 5000)) {
    if (!a || typeof a.n !== "string" || !Array.isArray(a.w)) continue;
    const w = a.w.filter(x => Array.isArray(x) && workKey(x[0]) && x[0].length <= 40 && !(x[0] in done) && /^https?:\/\//.test(String(x[6])))
      .map(x => [x[0], String(x[1] || "").slice(0, 200), +x[2] || 0, x[3] === "l" ? "l" : "s", String(x[4] || "").slice(0, 80), String(x[5] || "").slice(0, 10), String(x[6]).slice(0, 500),
        /^https:\/\//.test(String(x[7])) && String(x[7]).length <= 500 ? String(x[7]) : ""]);
    if (w.length) fresh.set(slug.slice(0, 120), { n: a.n.slice(0, 120), w });
  }
  const out = { new: [...fresh.values()].reduce((s, a) => s + a.w.length, 0), subscribers: 0, sent: 0, unsent: 0 };
  if (!fresh.size) return reply(out);
  const subs = await allKeys(KV, "w:"), mails = [];
  out.subscribers = subs.length;
  for (const k of subs) {
    const [sub, rec] = await Promise.all([KV.get(k.name, "json"), KV.get("u:" + k.name.slice(2), "json")]);
    if (!sub || !rec || !Array.isArray(rec.items)) continue;
    const found = rec.items.filter(x => x.startsWith("@") && fresh.has(x.slice(1))).map(x => fresh.get(x.slice(1)));
    if (found.length) mails.push({ to: sub.e, ...alertMail(sub.lang, found, site, sub.unsub) });
  }
  const used = await counted(env, "mail", today()), room = Math.max(0, Math.min(ALERTS_PER_DAY, MAIL_PER_DAY - used));
  const go = mails.slice(0, room);
  out.unsent = mails.length - go.length;
  if (go.length) await bump(env, "mail", go.length);
  if (env.SEND_MAIL) for (const m of go) await env.SEND_MAIL(m);
  else for (let i = 0; i < go.length; i += 100) {
    const r = await fetch("https://api.resend.com/emails/batch", {
      method: "POST", headers: { Authorization: "Bearer " + env.RESEND_API_KEY, "Content-Type": "application/json" },
      body: JSON.stringify(go.slice(i, i + 100).map(m => ({ from: env.MAIL_FROM || "museaal.ee <list@museaal.ee>", reply_to: "info@museaal.ee", ...m, to: [m.to] }))),
    });
    if (!r.ok) throw new Error("mail " + r.status);
  }
  out.sent = go.length;
  // announced, also when nobody was listening: an alert is for what is new, not for what was new before someone saved the artist
  for (const a of fresh.values()) for (const x of a.w) done[x[0]] = day;
  for (const [k, d] of Object.entries(done)) if (day - d > ALERTED_DAYS) delete done[k];
  await KV.put("x:alerted", JSON.stringify(done));
  return reply(out);
}

const mac = async (secret, s) => {
  const k = await crypto.subtle.importKey("raw", enc(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  return b64u(await crypto.subtle.sign("HMAC", k, enc(s)));
};
async function human(body, env, ip) {      // -> "" when the visitor may go on, a new pass, or null
  const now = Math.floor(Date.now() / 1000);
  const [exp, sig] = String(body.pass || "").split(".");
  if (+exp > now && +exp <= now + PASS_TTL && sig === await mac(env.TURNSTILE_SECRET, ip + "|" + exp)) return "";
  if (typeof body.human !== "string" || !body.human || body.human.length > 2048) return null;
  const f = new FormData();
  f.append("secret", env.TURNSTILE_SECRET); f.append("response", body.human); f.append("remoteip", ip);
  try {
    const v = await (await fetch("https://challenges.cloudflare.com/turnstile/v0/siteverify", { method: "POST", body: f })).json();
    if (!v.success) return null;
  } catch (e) { return null; }
  const until = now + PASS_TTL;
  return until + "." + await mac(env.TURNSTILE_SECRET, ip + "|" + until);
}

export default {
  async fetch(request, env, ctx) {
    const origin = request.headers.get("Origin") || "";
    const ok = ORIGINS.includes(origin);
    const cors = {
      "Access-Control-Allow-Origin": ok ? origin : ORIGINS[0],
      "Access-Control-Allow-Methods": "POST, OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type",
      "Access-Control-Max-Age": "86400",
      "Access-Control-Expose-Headers": "X-Museaal-Pass",
      "Vary": "Origin",
    };
    const more = {};     // a new Turnstile pass rides on the answer's headers
    const reply = (body, status = 200) => new Response(JSON.stringify(body), { status, headers: { ...cors, ...more, "Content-Type": "application/json" } });
    if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: cors });
    if (request.method !== "POST" || !ok) return reply({ error: "This service answers museaal.ee only." }, 403);
    let body = {};
    try { body = await request.json(); } catch (e) {}
    const ip = request.headers.get("CF-Connecting-IP") || "?", path = new URL(request.url).pathname;
    if (path.startsWith("/list/")) {
      if (tooMany(ip, syncs, 30)) return reply({ error: "Too many requests; wait a minute." }, 429);
      try { return await list(path.slice(6), body && typeof body === "object" ? body : {}, env, reply, ip); }
      catch (e) { console.log("list failed", String(e.message)); return reply({ error: "The list could not be reached." }, 502); }
    }
    if (path === "/alerts/send") {
      try { return await alerts(body && typeof body === "object" ? body : {}, env, reply, ip); }
      catch (e) { console.log("alerts failed", String(e.message)); return reply({ error: "The alerts could not be sent." }, 502); }
    }
    if (path === "/admin/stats") {
      try { return await admin(body && typeof body === "object" ? body : {}, env, reply, ip); }
      catch (e) { console.log("admin failed", String(e.message)); return reply({ error: "The figures could not be read." }, 502); }
    }
    // the two doors that call Claude, the mood page's at / and Buy Art's at /ask; any other address is no door
    if (path !== "/" && path !== "/ask") return reply({ error: "No such thing." }, 404);
    // a turn's later tool rounds count against the wider limit only. A round is a search turn's (tools)
    // with steps to show; ask() turns it away unless those steps unseal, so a made-up trail buys nothing
    const round = path === "/ask" && !!body.tools && Array.isArray(body.trail) && body.trail.length > 0;
    if (tooMany(ip, rounds, CALLS_PER_MINUTE) || !round && tooMany(ip)) return reply({ error: "Too many searches; wait a minute." }, 429);
    if (!env.ANTHROPIC_API_KEY) return reply({ error: "The service is not set up." }, 503);
    if (env.TURNSTILE_SECRET) {
      const pass = await human(body, env, ip);
      if (pass === null) return reply({ error: "Please confirm you are not a robot.", human: true }, 401);
      if (pass) more["X-Museaal-Pass"] = pass;
    }
    if (path === "/ask") {
      // the per-visitor limits live in each Worker instance's memory; this one holds across them all. Counted before
      // Claude is called, and a day that cannot be counted is a closed one: the cap guards what the key spends. A sealed
      // round can be sent again for its 10 minutes, so rounds have their own day's limit, ROUNDS to a question
      if (env.LISTS || env.COUNTS) {
        const n = await bump(env, round ? "round" : "ask").catch(e => { console.log("count failed", String(e.message)); return Infinity; });
        if (n > (round ? ASK_PER_DAY * ROUNDS : ASK_PER_DAY)) return reply({ error: "The assistant has answered all it can for today; try again tomorrow." }, 429);
      }
      return ask(body, env, reply, ip);
    }

    let q = "";
    try { q = String(body.q || "").replace(/\s+/g, " ").trim().slice(0, 200); } catch (e) {}
    if (!q) return reply({ error: "Nothing to read." }, 400);
    // a reading counted in D1, or without it in KV for one reading in ten, by ten: readings cannot spend KV's
    // 1,000 writes a day (on the free plan) that sign-in and the lists need
    if (env.COUNTS) later(ctx, bump(env, "mood")); else if (Math.random() < 0.1) later(ctx, bump(env, "mood", 10));

    let r;
    try {
      r = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "x-api-key": env.ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01", "content-type": "application/json" },
        body: JSON.stringify({
          model: MODEL, max_tokens: 2000, system: SYSTEM,     // room for its thinking as well as the few words
          messages: [{ role: "user", content: q }],
          output_config: { effort: "low", format: { type: "json_schema", schema: SCHEMA } },
        }),
      });
    } catch (e) { return reply({ error: "The reader could not be reached." }, 502); }
    if (!r.ok) { await refused(r, "mood"); return reply({ error: "The reader answered " + r.status + "." }, 502); }

    const m = await r.json();
    if (m.stop_reason === "refusal") return reply({ words: [], kind: "keep" });
    let out;
    try { out = JSON.parse((m.content || []).filter(b => b.type === "text").map(b => b.text).join("")); }
    catch (e) { return reply({ error: "The reader's answer was unreadable." }, 502); }
    const words = [...new Set((out.words || []).filter(w => WORDS.includes(w)))].slice(0, 5);
    const kind = ["paint", "paper", "all"].includes(out.kind) ? out.kind : "keep";
    return reply({ words, kind });
  },
};
